def min_cost_permutation(n, tags):
    from collections import defaultdict

    # Count the frequency of each tag
    tag_count = defaultdict(int)
    for tag in tags:
        tag_count[tag] += 1

    # Check if it's possible to avoid consecutive tags
    for count in tag_count.values():
        if count > (n + 1) // 2:
            return -1

    # Find the most frequent tag
    max_freq_tag = max(tag_count, key=tag_count.get)

    # Calculate the initial cost by counting jumps
    cost = 0
    for i in range(n - 1):
        if tags[i] == tags[i + 1]:
            cost += 1

    # Try to reduce the cost by swapping non-adjacent tags
    for i in range(n):
        if tags[i] != max_freq_tag:
            for j in range(n):
                if tags[j] != max_freq_tag and i != j:
                    # Swap tags[i] and tags[j]
                    tags[i], tags[j] = tags[j], tags[i]
                    # Calculate the new cost
                    new_cost = 0
                    for k in range(n - 1):
                        if tags[k] == tags[k + 1]:
                            new_cost += 1
                    cost = min(cost, new_cost)
                    # Swap back to original
                    tags[i], tags[j] = tags[j], tags[i]

    return cost

